old=json.loads((SRC/'coverage_summary.json').read_text())['ghs_2023_G057_2013_epoch2015'];im=ee.Image('JRC/GHSL/P2023A/GHS_POP/2010').select('population_count');region=ee.Geometry.Rectangle(old['native_frame_lonlat'],'EPSG:4326',False);raw=im.rename('count').addBands(im.mask().rename('validmask')).toDouble().sampleRectangle(region,defaultValue=-9999).getInfo()['properties'];a=np.array(raw['count'],float);m=np.array(raw['validmask'],float);assert np.all(np.isfinite(a)&(m>0)&(a>=0));name='ghs_2023_G057_2013_epoch2010';np.savez_compressed(OUT/(name+'.npz'),count=a,mask=m);new={**old,'asset':'JRC/GHSL/P2023A/GHS_POP/2010','selected_epoch':2010,'source_projection':im.getInfo()['bands'][0],'native_frame_shape':list(a.shape)};(OUT/'extra_epoch_metadata.json').write_text(json.dumps({name:new},indent=2)+'\n');print(name,a.shape,'positive',(a>0).sum(),flush=True)
